import time
import random

def construct():
       N = 1000
       deadline = time.time() + 135  # Safety margin (15s buffer)

       def is_valid_addition(counts, x, chosen_set):
           # Check if adding x to the set defined by counts is valid
           # We need to check sums x + y for y in chosen_set, and 2*x
           # But counts already includes sums from chosen_set.
           # We just need to see if adding x's contribution pushes any sum > 2.
           
           # Sums generated by x:
           # x + y for y in chosen_set where y <= x ? No, a<=b.
           # If we add x, new pairs are (x, y) with y in chosen_set, y <= x? 
           # Actually, the set is a set. Order doesn't matter for the set of sums.
           # Pairs are {a,b} with a<=b.
           # If we add x, new pairs are:
           # 1. (x, x) -> sum 2x
           # 2. (y, x) for y in chosen_set, y < x. (Since y < x, pair is y, x)
           #    Note: pairs (x, y) with y > x are already counted as (y, x) in the existing set? 
           #    No, the existing set doesn't have x.
           #    So new pairs are {x, y} for all y in chosen_set.
           #    Since we require a <= b, if y < x, pair is (y, x). If y > x, pair is (x, y).
           #    Wait, the condition is a <= b.
           #    So for any y in chosen_set, the pair is (min(x,y), max(x,y)).
           #    The sum is x+y.
           
           # So we check counts[x+y] + 1 <= 2 for all y in chosen_set, and counts[2x] + 1 <= 2.
           
           for y in chosen_set:
               s = x + y
               if counts.get(s, 0) + 1 > 2:
                   return False
           if counts.get(2*x, 0) + 1 > 2:
               return False
           return True

       def update_counts_add(counts, x, chosen_list):
           for y in chosen_list:
               s = x + y
               counts[s] = counts.get(s, 0) + 1
           s = 2*x
           counts[s] = counts.get(s, 0) + 1

       def update_counts_remove(counts, x, chosen_list):
           for y in chosen_list:
               s = x + y
               counts[s] -= 1
               if counts[s] == 0:
                   del counts[s]
           s = 2*x
           counts[s] -= 1
           if counts[s] == 0:
                   del counts[s]

       best_set = set()
       best_size = 0
       
       # Multiple random greedy starts
       # Since max size is small, we can try many starts.
       # But local search is more important.
       
       def greedy_random():
           chosen = set()
           chosen_list = []
           counts = {}
           candidates = list(range(1, N+1))
           random.shuffle(candidates)
           for x in candidates:
               if is_valid_addition(counts, x, chosen_list):
                   chosen.add(x)
                   chosen_list.append(x)
                   update_counts_add(counts, x, chosen_list)
           return chosen, chosen_list, counts

       def local_search(chosen, chosen_list, counts, time_limit):
           """
           Local search with maintained chosen_list for efficiency.
           chosen: set for O(1) membership
           chosen_list: list for O(n) iteration in validity checks
           counts: dict of sum -> count
           """
           stuck_counter = 0
           all_candidates = set(range(1, N+1))
           
           while time.time() < time_limit:
               # 1. Try to add
               added = False
               # Try random candidates not in chosen
               for _ in range(20):  # Increased attempts
                   x = random.randint(1, N)
                   if x in chosen:
                       continue
                   if is_valid_addition(counts, x, chosen_list):
                       chosen.add(x)
                       chosen_list.append(x)
                       update_counts_add(counts, x, chosen_list)
                       added = True
                       stuck_counter = 0
                       break
               
               if added:
                   continue
                   
               # 2. Try Swap
               # Pick x in chosen, y not in chosen
               # If swap is valid, do it.
               swapped = False
               for _ in range(20):  # Increased attempts
                   if not chosen_list:
                       break
                   idx_out = random.randint(0, len(chosen_list)-1)
                   x_out = chosen_list[idx_out]
                   x_in = random.randint(1, N)
                   if x_in in chosen:
                       continue
                   
                   # Check swap validity
                   # Remove x_out temporarily
                   update_counts_remove(counts, x_out, chosen_list)
                   chosen.discard(x_out)
                   # Remove from list (swap with last for O(1) removal)
                   chosen_list[idx_out] = chosen_list[-1]
                   chosen_list.pop()
                   
                   if is_valid_addition(counts, x_in, chosen_list):
                       # Accept swap
                       chosen.add(x_in)
                       chosen_list.append(x_in)
                       update_counts_add(counts, x_in, chosen_list)
                       swapped = True
                       stuck_counter = 0
                   else:
                       # Revert
                       chosen.add(x_out)
                       chosen_list.append(x_out)
                       update_counts_add(counts, x_out, chosen_list)
                   
                   if swapped:
                       break
                       
               if not swapped and not added:
                   stuck_counter += 1
                   if stuck_counter > 500:
                       break

           return chosen, chosen_list, counts

       # Main loop
       # Try a few greedy starts, then local search on the best
       
       # 1. Get a good initial set
       # Run greedy a few times, keep the largest
       init_sets = []
       for i in range(8):  # More initial attempts
           s, sl, c = greedy_random()
           init_sets.append((len(s), s, sl, c))
           
       init_sets.sort(key=lambda x: x[0], reverse=True)
       best_size, best_set, best_list, best_counts = init_sets[0]
       
       # 2. Local Search on the best
       # Allocate remaining time
       current_time = time.time()
       remaining = deadline - current_time - 5
       
       if remaining > 10:
           best_set, best_list, best_counts = local_search(best_set, best_list, best_counts, current_time + remaining)
           best_size = len(best_set)
       
       # 3. If we have time, try local search on second-best initial set
       current_time = time.time()
       remaining = deadline - current_time - 3
       if remaining > 15 and len(init_sets) > 1:
           second_size, second_set, second_list, second_counts = init_sets[1]
           # Only if it's close in size
           if second_size >= best_size - 3:
               s2, l2, c2 = local_search(second_set, second_list, second_counts, current_time + remaining)
               if len(s2) > best_size:
                   best_size = len(s2)
                   best_set = s2
                   best_list = l2
                   best_counts = c2
       
       return sorted(best_set)
